function mount(el,c){if(M.PASSERELLE_CONTENT_V1217?.items?.[c.id])return;let g=gallery(c.id);if(!g)return;el.querySelectorAll('.r37-gallery').forEach(x=>x.remove());let anchor=el.querySelector('#ph-apply');if(anchor)anchor.insertAdjacentHTML('beforebegin',g);else(el.querySelector('.lesson-main')||el).insertAdjacentHTML('beforeend',g);}
function valid(q){if(!q||!q.id||!q.chapterId||!String(q.prompt||'').trim()||q.assessmentActive===false)return false;switch(q.type||q.format||'mc'){case 'numeric':return Number.isFinite(q.answer)&&(q.tolerance==null||Number.isFinite(q.tolerance)&&q.tolerance>=0);case 'mc':return q.options?.length>1&&Number.isInteger(q.answer)&&q.answer>=0&&q.answer<q.options.length;case 'truefalse':return typeof q.answer==='boolean';case 'cloze':case 'correction':return typeof q.answer==='string'&&!!q.answer.trim();case 'selection':return q.options?.length>1&&q.answers?.length>0&&new Set(q.answers).size===q.answers.length&&q.answers.every(i=>Number.isInteger(i)&&i>=0&&i<q.options.length);case 'match':return q.pairs?.length>1&&q.pairs.every(p=>p.length===2&&String(p[0]).trim()&&String(p[1]).trim());case 'order':return q.items?.length>1&&q.answer?.length===q.items.length&&new Set(q.answer).size===q.items.length&&q.answer.every(i=>Number.isInteger(i)&&i>=0&&i<q.items.length);default:return false;}}
