function paintProof(){let d=document.getElementById('r37-proof'),profile=d.querySelector('select').value,q=d.querySelector('input').value.toLocaleLowerCase();let list=proofData.rows.filter(r=>(!profile||r.profiles.includes(profile))&&(!q||(r.title+' '+r.id+' '+r.subject).toLocaleLowerCase().includes(q)));d.querySelector('#r37-proof-count').textContent=list.length+' Module. Test startbar bedeutet mindestens sechs technisch verwendbare Fragen, nicht abgeschlossene Kompetenzabdeckung.';d.querySelector('.r37-proof-rows').innerHTML=list.map(r=>'<article class="r37-proof-row"><div><h3>'+esc(r.title)+'</h3><code>'+esc(r.id)+'</code></div><dl><div><dt>Lehrtext</dt><dd>'+r.blocks+' gespeicherte Abschnitte</dd></div><div><dt>Visuals dieses Updates</dt><dd>'+r.visualIds.length+'</dd></div><div><dt>Testfragen / &Uuml;bungspool</dt><dd>'+r.questions+' / '+r.practice+'</dd></div><div><dt>Test technisch startbar</dt><dd>'+(r.questions>=6?'Ja':'Nein')+'</dd></div><div><dt>Lehrplan und Fachfreigabe</dt><dd>Nicht vollst&auml;ndig nachgewiesen</dd></div></dl><details><summary>Quellen, Profile und Visual-IDs</summary><p>'+esc(r.profiles.join(', ')||'Keine direkte Planbindung; Wiederverwendung separat kontrollieren.')+'</p><p>'+esc(r.sourceRefs.join(', ')||'Keine Quelle verknuepft.')+'</p><p>'+esc(r.visualIds.join(', ')||'Kein Visual aus diesem Update.')+'</p></details>'+(profile?'<button type="button" data-r37-open-module="'+esc(r.id)+'" data-r37-profile="'+esc(profile)+'">Modul &ouml;ffnen</button>':'')+'</article>').join('');}
document.addEventListener('click',e=>{let b=e.target.closest?.('[data-r37-proof],[data-r37-open-module]');if(!b)return;if(b.hasAttribute('data-r37-proof')){openProof();return;}let p=proofData.plans.find(x=>x.configurationId===b.dataset.r37Profile);if(!p)return;document.getElementById('r37-proof').close();M.setProgram(p.programmeId);if(!M.setConfiguration(p.programmeId,p.configurationId))throw Error('Profile switch failed');M.go('read',b.dataset.r37OpenModule);});

