 while((x=re.exec(t))){ var vor=t.slice(Math.max(0,x.index-3),x.index+1); if(/\b(z|d|u|bzw|ca|vgl|Nr|S)\.$/.test(vor)) continue; if(x.index>=10){ ende=x.index+1; break; } }
 var aufgabe= ende>0? t.slice(0,ende).trim() : t, rest= ende>0? t.slice(ende).trim() : '';
 var teile=rest.split(/\.\s+/), ergebnis=teile.length>1? teile[teile.length-1].trim() : '';
